mapper.select:
SELECT r.id, r.user_id AS userId, COALESCE(ba.nickname, ba.username) AS nickname, r.model_id AS modelId, m.model_name AS modelName, r.role_id AS roleId, ar.role_name AS roleName, ar.role_avatar AS roleAvatar, r.title, r.chat_type AS chatType, r.is_top AS isTop, r.total_tokens AS totalTokens, r.create_time AS createTime, r.update_time AS updateTime FROM bedrock_ai_chat_record r LEFT JOIN bedrock_ai_model m ON r.model_id = m.id AND m.is_deleted = 0 LEFT JOIN bedrock_ai_role ar ON r.role_id = ar.id AND ar.is_deleted = 0 LEFT JOIN bedrock_admin ba ON r.user_id = ba.id AND ba.is_deleted = 0 WHERE r.is_deleted = 0
AND r.title LIKE concat('%', #{param.title}, '%')
AND r.user_id = #{param.userId}
AND (ba.nickname LIKE concat('%', #{param.nickname}, '%') OR ba.username LIKE concat('%', #{param.nickname}, '%'))
AND r.model_id = #{param.modelId}
AND r.chat_type = #{param.chatType}
AND r.update_time >= #{param.startTime}
AND r.update_time <= #{param.endTime}
ORDER BY r.update_time DESC
